// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;

    function setUp() public {
        c = new FlashGovernanceArbiter(address(new __InvMutHandleStub()));
    }

    function testFuzz_property(address caller, address dao) public {
        // Reference C has not been configured, so the only guard that can fire is
        // msg.sender == DAO with the stub DAO address = address(this) of InvMutTest.
        // Any caller is admissible as long as it is not the setUp DAO (the stub),
        // and we pick an arbitrary non-caller, non-zero value for dao.
        vm.assume(caller != address(0));
        vm.assume(dao != caller);

        vm.prank(caller);
        c.setDAO(dao);

        // General rule: the value written to DAO is exactly the argument passed.
        assertTrue(c.DAO() == dao, "setDAO must store the dao argument, not msg.sender");
    }
}

